+fn sinker_block() -> Mesh {
+    let raw = pocket_support::height_field(&[-30.0, -1.1, 9.1, 30.0], &[-30.0, -6.1, 0.1, 30.0], |i, j| if (i, j) == (1, 1) { 14.0 } else { 20.0 });
